"use client";

import { Button } from "@/components/baseui/components/button";
import {
	PopoverRoot,
	PopoverTrigger,
	PopoverPortal,
	PopoverPositioner,
	PopoverPopup,
	PopoverTitle,
	PopoverDescription,
	PopoverArrow,
} from "@/components/baseui/components/popover";

export default function Particle() {
	return (
		<PopoverRoot>
			<PopoverTrigger
				render={<Button variant="outline">Open Popover</Button>}
			/>
			<PopoverPortal>
				<PopoverPositioner>
					<PopoverPopup>
						<PopoverArrow />
						<PopoverTitle>Popover Title</PopoverTitle>
						<PopoverDescription>
							This is a simple popover description.
						</PopoverDescription>
					</PopoverPopup>
				</PopoverPositioner>
			</PopoverPortal>
		</PopoverRoot>
	);
}
